var V3_SETTINGS = localStorage.getItem("v3_local_db");
V3_SETTINGS = JSON.parse(V3_SETTINGS) || {config:{db:{yt:{}}}};
var V3_SETTINGS_CONF = V3_SETTINGS.config.db.yt;
var STS = ugfStGet(theSets);
if (STS !== null) {
    SRS = STS.radioSettings;
}
    window.addEventListener('keydown', (event) => {
        if (event.altKey && event.shiftKey) {
            if (event.code === 'KeyC') {
                $("html").setAttribute("densor-closed","true");
                $("html").removeAttribute("densor-tut");
                STS.show2point7=false;
                applySettings(0);
                showHideSettings();
            }
        }
    });
function STX_checkClick(e){
    if(e.target){
        if(e.target.classList.contains("stx-trigger")){
            let type=e.target.getAttribute("stx-trigger-type");
            if(type=="attrib-tog"){
                $(e.target.getAttribute("stx-target")).toggleAttribute(e.target.getAttribute("stx-attrib"));
            }
        }
    }
}

async function STX_craftLink(elm,ep,id,href,params){
    return new Promise((resolve, reject) => {
        ep!==null&&elm.setAttribute("stx-ep",ep);
        id!==null&&elm.setAttribute("stx-id",id);
        href!==null&&elm.setAttribute("href",href);
        href!==null&&elm.setAttribute("stx-href",href);
        if(params){
            elm.setAttribute("stx-params",params);
        }
        elm.classList.add("stx-link");
        resolve(elm);
    });
}
function STX_warmLink(a){
    let ep=a.getAttribute("stx-ep");
    let id=a.getAttribute("stx-id");
    let href=a.href;
    if(href.includes("youtube.com")){
       href=href.split("youtube.com")[1];
    }
    let params=a.getAttribute("stx-params");
    if(ep=="browse"){
        if(params){
            a.data = {
                abstractVorElement: {
                    navigationEndpoint: {
                        browseEndpoint: {
                            browseId:id,
                            canonicalBaseUrl:href,
                            params:params
                        },
                        commandMetadata: {
                            webCommandMetadata: {
                                url:href
                            }
                        }
                    }
                }
            }
        }else{
            a.data = {
                abstractVorElement: {
                    navigationEndpoint: {
                        browseEndpoint: {
                            browseId:id,
                            canonicalBaseUrl:href
                        },
                        commandMetadata: {
                            webCommandMetadata: {
                                url:href
                            }
                        }
                    }
                }
            }
        }
    }else if(ep=="watch"){
        if(params){
            a.data={
                abstractVorElement:{
                    navigationEndpoint:{
                        watchEndpoint:{
                            videoId:id,
                            playlistId:params,
                            canonicalBaseUrl:href
                        },
                        commandMetadata:{
                            webCommandMetadata:{
                                url:href
                            }
                        }
                    }
                }
            }
        }else{
            a.data = {
                abstractVorElement: {
                    navigationEndpoint: {
                        watchEndpoint: {
                            videoId:id,
                            canonicalBaseUrl:href
                        },
                        commandMetadata: {
                            webCommandMetadata: {
                                url:href
                            }
                        }
                    }
                }
            }
        }
    }
}
window.addEventListener("resize",getVideoSize);
window.addEventListener("click",STX_checkClick);
