	function doThirdColumnVideos(){ try { return doThirdColumnVideos__ugf.apply(this, arguments); } catch (e) { console.log("Gplex Extended for YouTube: doThirdColumnVideos: " + (e && e.message) + " " + String(e && e.stack || "").split("\n")[1]); } }
	function doThirdColumnVideos__ugf(){
		if($(".feed .branded-page-v2-secondary-col #startube-third-column") == null && $(".feed .branded-page-v2-secondary-col .branded-page-box")){
			let container = $(".feed .branded-page-v2-secondary-col .branded-page-box");
			let newElem = document.createElement("div");
			newElem.id = "startube-third-column";
			newElem.innerHTML = ugfTT(`
			<div id="startube-spotlight">
				<h3>Hype</h3>
			</div>
			<ul id="thirdcol-videos" class="video-list">
			</ul>
				`);
			container.insertBefore(newElem, container.children[0]);
			if(gdp.thirdColVideos == null){
                mobileFetch("none","nomod","browse","browseId","FEhype_leaderboard").then(result => {
                    fillThirdCol(result);
					gdp.thirdColVideos = result;
                });
			}else{
				fillThirdCol(gdp.thirdColVideos);
			}
		}
	}
	function fillThirdCol(result){
		/*let shelf=result.contents.twoColumnBrowseResultsRenderer.tabs[0].tabRenderer.content.sectionListRenderer.contents[1].itemSectionRenderer.contents[0].shelfRenderer.content.expandedShelfContentsRenderer.items;
		shelf.forEach(i => {
			if(i.videoRenderer){
				createRenderer(i.videoRenderer, "thirdColCompactVideo");
			}
		});*/
        let list;
        let number=0;
        list=result.contents.singleColumnBrowseResultsRenderer.tabs[0].tabRenderer.content.sectionListRenderer.contents;
        list.forEach(i => {
            if(i.itemSectionRenderer.contents[0].elementRenderer.newElement.type.componentType.model.compactVideoModel){
                createRenderer(i.itemSectionRenderer.contents[0].elementRenderer.newElement.type.componentType.model.compactVideoModel.compactVideoData, "thirdColCompactVideo", number);
                number++;
            }
        });
	}
    // EXfunct
	function replaceFavicon(favi){
		if(favi!=="2012"){
			let icoElm=$("head [rel='icon']");
			let timeout=100;
			if($("#st-favi")==null){
				let clone=icoElm.cloneNode(true);
				clone.id="st-favi";
				$("head").appendChild(clone);
				icoElm.remove();
				icoElm=clone;
				timeout=3000;
			}
			setTimeout(function(){
				switch (favi){
					case "2024":
						icoElm.href="https://www.youtube.com/s/desktop/9fa451de/img/logos/favicon_32x32.png";
						break;
					case "2024_old":
						icoElm.href="https://www.youtube.com/s/desktop/71ca99b3/img/logos/favicon.ico";
						break;
					case "2017":
						icoElm.href="https://www.youtube.com/s/desktop/daa4e47c/img/favicon_32x32.png";
						break;
					case "2015":
						icoElm.href="https://s.ytimg.com/yts/img/favicon_32-vfl8NGn4k.png";
						break;
					case "2012":
						icoElm.href="https://s.ytimg.com/yts/img/favicon-vfldLzJxy.ico";
						break;
					case "2010":
						icoElm.href="https://s.ytimg.com/yt/favicon-vflZlzSbU.ico";
						break;
					case "2005":
						icoElm.href="https://s.ytimg.com/yt/favicon-vfl1123.ico";
						break;
					default:
				}
			}, timeout);
		}
	}
