    function createDensorTrigger__ugf(){
        return; // (Gplex)
        let conta=$("body");
        let nE=document.createElement("div");
        nE.id="st-densor-trig";
        nE.classList.add("flex-bar");
        nE.innerHTML=ugfTT(`
        <span>Keep hovering to open Gplex Extended for YouTube Settings (or press Alt + Shift + C)</span>
        `);
        conta.append(nE);
        function showOverlay() {
            if($("#startube-settings-window-entity.hid")!=null){
                $("#startube-settings-window-entity").classList.remove("hid");
            }
            $("html").setAttribute("densor-trig","inactive");
            STS.show2point7=false;
            applySettings(0);
            $("html").setAttribute("densor-closed","true");
            $("html").removeAttribute("densor-tut");
        }
        function phase5(){
            $("html").setAttribute("densor-trig","active3");
            setTimeout(function(){
                if(nE.matches(':hover')){
                    showOverlay();
                }else{
                    $("html").setAttribute("densor-trig","inactive");
                }
            },250);
        }
        function phase4(){
            $("html").setAttribute("densor-trig","active2");
            setTimeout(function(){
                if(nE.matches(':hover')){
                    phase5();
                }else{
                    $("html").setAttribute("densor-trig","inactive");
                }
            },250);
        }
        function phase3(){
            $("html").setAttribute("densor-trig","active1");
            setTimeout(function(){
                if(nE.matches(':hover')){
                    phase4();
                }else{
                    $("html").setAttribute("densor-trig","inactive");
                }
            },250);
        }
        function phase2(){
            $("html").setAttribute("densor-trig","active0");
            setTimeout(function(){
                if(nE.matches(':hover')){
                    phase3();
                }else{
                    $("html").setAttribute("densor-trig","inactive");
                }
            },250);
        }
        nE.addEventListener('mouseenter', function (e) {
            setTimeout(function(){
                if(nE.matches(':hover')){
                    phase2();
                }
            }, 250);
        });
        nE.addEventListener('mouseleave', function (e) {
            $("html").setAttribute("densor-trig","inactive");
        });
    }
