// (5.10) The Search Settings saved on Gplex's settings page, put into every search: added to
// the address as Google's own settings when the search did not say otherwise.
(function ugfSearchPrefsApply() {
    try {
        if (window.location.host !== "www.google.com" || window.top !== window.self || !/^\/search\/?$/.test(window.location.pathname || "") ||
                /[?&]gplex=false\b/.test(window.location.search || "")) {
            return;
        }
        const get = function(k) {
            try {
                return String(window.localStorage.getItem(k) || "");
            } catch (e) {
                return "";
            }
        };
        const p = new URLSearchParams(window.location.search);
        let changed = false;
        const add = function(name, v) {
            if (v && !p.has(name)) {
                p.set(name, v);
                changed = true;
            }
        };
        add("safe", get("UGF_PREF_SAFE"));
        add("lr", get("UGF_PREF_LR"));
        add("hl", get("UGF_PREF_HL"));
        add("gl", get("UGF_PREF_GL"));
        const num = get("UGF_PREF_NUM");
        add("num", num && num !== "10" ? num : "");
        if (changed && p.get("q")) {
            window.location.replace(window.location.pathname + "?" + p.toString() + window.location.hash);
            return;
        }
        // "Open search results in a new browser window"
        if (get("UGF_PREF_NEWWIN") === "1") {
            document.addEventListener("click", function(ev) {
                const a = ev.target && ev.target.closest ? ev.target.closest(".ugf-search-result a[href]") : null;
                if (!a || ev.ctrlKey || ev.metaKey || ev.shiftKey || ev.button !== 0) {
                    return;
                }
                const href = a.getAttribute("href") || "";
                if (!/^https?:\/\//.test(href) || /^https?:\/\/www\.google\.com\/search/.test(href)) {
                    return;
                }
                ev.preventDefault();
                ev.stopPropagation();
                window.open(href, "_blank", "noopener");
            }, true);
        }
    } catch (e) {}
})();
