if (window.location.host === "accounts.google.com") {
    return;
}
// myaccount.google.com is only restyled (by ugfMyAccountTheme above)
if (window.location.host === "myaccount.google.com" || window.location.host === "keep.google.com") {
    return;
}
// the Advanced Search page is Gplex's own (ugfAdvancedSearch above), or Google's on 2022
if (window.location.host === "www.google.com" && /^\/(advanced_search|preferences)\/?$/.test(window.location.pathname || "")) {
    return;
}
