        const apps = dark
            ? ["Search", "Images", "Maps", "Play", "YouTube", "News", "Gmail", ugfDocsLabel(), "Drive", "Calendar"].filter(ugfDvGbarKeep)
            : (era === "g2010"
                ? ["Web", "Images", "Videos", "Maps", "News", "Shopping", "Gmail", ugfDocsLabel()]
                : ["Web", "Images", "Video", "Maps", "News", "Shopping", "Gmail", ugfDocsLabel()]);
        let links = plus
