        add("[jsname='OCpkoe'] *, [jsname='M2UYVd'] *, [jsname='GeGHKb'] *", "font-size: " + (kennedy ? "11px" : "13px") + " !important; font-weight: " + (kennedy ? "bold" : "normal") + " !important; color: inherit !important; text-transform: none !important;");
